/**
 * Chat streaming helpers for Slack AI / agent features.
 */
export function markdownChunk(text) {
    return { type: "markdown_text", text };
}
/**
 * Given previously sent cumulative text and the new cumulative text, return
 * the suffix to append. Empty string when there is nothing new to send.
 */
export function computeStreamAppend(lastPostedText, cumulative) {
    if (cumulative === "") {
        return "";
    }
    if (lastPostedText === null || lastPostedText === undefined || lastPostedText === "") {
        return cumulative;
    }
    if (cumulative.startsWith(lastPostedText)) {
        return cumulative.slice(lastPostedText.length);
    }
    // Text rewound / rewritten — cannot unsend; skip append.
    return "";
}
/** Clamp to `max` characters, ending in an ellipsis when cut. */
export function truncateCardText(text, max) {
    if (text.length <= max) {
        return text;
    }
    return `${text.slice(0, max - 1)}…`;
}
